(async()=>{
 const wait=()=>new Promise(r=>setTimeout(r,160)),check=(v,m)=>{if(!v)throw Error(m)},state=()=>JSON.parse(localStorage.getItem('collaboration-prototype-v1')),dialog=()=>document.querySelector('dialog[open]');
 const go=async p=>{location.hash=p;await wait()},click=async(t,scope=document)=>{const e=[...scope.querySelectorAll('button,a')].find(e=>(e.textContent.trim()===t||e.getAttribute('aria-label')===t)&&!e.disabled);check(e,'Missing '+t);e.click();await wait()};
 const fill=async(label,value)=>{const e=document.querySelector(`[aria-label="${label}"]`)||document.querySelector(`[name="${label}"]`);check(e&&!e.disabled,'Missing enabled '+label);Object.getOwnPropertyDescriptor(e.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(e,value);e.dispatchEvent(new Event('input',{bubbles:true}));await wait()};
 const tab=async t=>{const e=[...dialog().querySelectorAll('[role=tab]')].find(e=>e.textContent.trim()===t);check(e,'Missing tab '+t);e.click();await wait()},checks=[];
 await go('/chat?channel_id=external');await click('频道设置');const bounds=dialog().getBoundingClientRect();await tab('外部会话');const after=dialog().getBoundingClientRect();check(Math.abs(bounds.width-after.width)<1&&Math.abs(bounds.height-after.height)<1,'Tab resized settings dialog');check(location.hash.includes('state.channel-management-tab'),'Management tab not deep linked');
 const select=document.querySelector('[role=combobox][aria-label="连接器"]');check(select,'Missing connector selector');select.click();await wait();const option=[...document.querySelectorAll('[role=option]')].find(e=>e.textContent.includes('Slack'));check(option,'Slack connector missing');option.click();await wait();
 await fill('外部频道 / 会话 ID','C-REVIEW');await fill('外部会话名称','外部评审');await click('保存绑定');const channel=()=>state().channels.find(c=>c.id==='external');check(channel().externalBridge?.platform==='Slack','Binding missing');
 await fill('固定外部消息 ID','external-review-1');await fill('外部消息正文','外部方向已确认');await click('模拟接收到当前频道');const incoming=state().messages.filter(m=>m.source?.externalMessageId==='external-review-1');check(incoming.length===1&&incoming[0].channel==='external','Incoming not in bound channel');check(document.querySelector('.messages').textContent.includes('外部方向已确认')&&document.querySelector('.messages').textContent.includes('Slack · 外部来源'),'Message/source badge absent from chat');
 await fill('外部消息正文','不得覆盖原文');await click('模拟接收到当前频道');check(state().messages.filter(m=>m.source?.externalMessageId==='external-review-1').length===1,'Duplicate external event duplicated chat');
 await fill('回复正文','收到，按已确认方向执行');await click('保存回复草稿，不发送');check(channel().externalOutbox.at(-1).status==='DRAFT'&&!channel().externalOutbox.at(-1).receipt,'Draft sent without approval');const authorize=[...dialog().querySelectorAll('button')].find(e=>e.textContent.trim()==='Human 确认授权');check(authorize?.disabled,'Authorization lacks explicit confirmation');
 const checkbox=[...dialog().querySelectorAll('label')].find(e=>e.textContent.includes('我已核对上述目标')).querySelector('input');checkbox.click();await wait();await click('Human 确认授权');await click('执行已授权的本地模拟');const receipt=channel().externalOutbox.at(-1).receipt;check(receipt&&receipt.delivered===false,'Simulation receipt absent/false delivery');checks.push('Slack binding visible in chat; fixed incoming dedup; explicit Human reply authorization; honest receipt');
 await click('暂停收发');check(channel().externalBridge.status==='PAUSED'&&document.querySelector('[name="外部消息正文"]').disabled,'Pause not blocking input');await click('恢复绑定');await click('撤销绑定并保留历史');check(channel().externalBridge.status==='REVOKED'&&channel().externalOutbox.at(-1).receipt.id===receipt.id&&channel().externalBridgeHistory.length>=5,'Revoke lost history');checks.push('pause/resume/revoke retain messages and receipts; fixed modal geometry');
 await go('/chat?channel_id=launch');await click('频道设置');await tab('外部会话');check(dialog().textContent.includes('内部、私聊与执行频道不开放')&&!dialog().querySelector('[aria-label="连接器"]'),'Internal bridge exposed');check(document.documentElement.scrollWidth<=innerWidth,'Viewport overflow');return {pass:true,width:innerWidth,checks};
})();
